import{obterJSON,endereco,consultaLimpa,pontuarCorrespondencia}from'./comum.js';
export function converterEuropePmc(item){const id=String(item?.pmcid||item?.pmid||item?.doi||'').trim();if(!id)return null;const pmcid=String(item?.pmcid||'').trim(),source=String(item?.source||'MED').trim(),ext=String(item?.id||item?.pmid||item?.doi||id),ler=endereco(pmcid?`https://europepmc.org/articles/${pmcid}`:`https://europepmc.org/article/${encodeURIComponent(source)}/${encodeURIComponent(ext)}`);if(!ler)return null;const autores=Array.isArray(item?.authorList?.author)?item.authorList.author.map(a=>a?.fullName||[a?.firstName,a?.lastName].filter(Boolean).join(' ')).filter(Boolean):(item?.authorString?String(item.authorString).split(',').map(x=>x.trim()).filter(Boolean):[]);const descricao=[item?.journalTitle,item?.pubYear,item?.pubTypeList?.pubType?.[0]].filter(Boolean).join(' · ');return{id:`europepmc:${id}`,fonte:'europepmc',provedor:'Europe PMC',titulo:String(item.title||'Sem título'),autores,idiomas:[],capa:null,descricao,acessoLivre:true,dominioPublico:false,tipoAcesso:pmcid?'Artigo científico · texto integral':'Artigo científico aberto',licenca:'Publicação marcada como Open Access no Europe PMC. A licença específica é informada no registro do artigo.',origem:ler,ler,texto:null,formatos:[]}}
export async function pesquisarEuropePmc(q,o={}){const termo=consultaLimpa(q);if(!termo)return{livros:[],total:0,temMais:false};const pagina=Math.max(1,o.pagina||1),u=new URL('/api/acervos-gratuitos',location.origin);u.searchParams.set('fonte','europepmc');u.searchParams.set('q',termo);u.searchParams.set('pagina',String(pagina));const d=await obterJSON(u,14000,2),itens=Array.isArray(d?.resultList?.result)?d.resultList.result:[],livros=itens.map(converterEuropePmc).filter(Boolean);for(const l of livros)l.relevancia=pontuarCorrespondencia(termo,l.titulo,l.autores);livros.sort((a,b)=>(b.relevancia||0)-(a.relevancia||0));const total=Number(d?.hitCount)||livros.length;return{livros,total,temMais:pagina*20<total&&itens.length>0}}
